int erdma_req_notify_cq ( struct ib_cq * ibcq , enum ib_cq_notify_flags flags ) { struct erdma_cq * cq = to_ecq ( ibcq ) ; cfs_time_t irq_flags ; int ret = 0 ; spin_lock_irqsave ( & cq -> kern_cq . lock , irq_flags ) ; notify_cq ( cq , ( flags & IB_CQ_SOLICITED_MASK ) == IB_CQ_SOLICITED ) ; if ( ( flags & IB_CQ_REPORT_MISSED_EVENTS ) && get_next_valid_cqe ( cq ) ) { ret = 1 ; } cq -> kern_cq . notify_cnt ++ ; spin_unlock_irqrestore ( & cq -> kern_cq . lock , irq_flags ) ; return ret ; } 